import java.util.*;

public class Main {
    static Scanner scanner = new Scanner(System.in);

    static String readLn() {
        return scanner.nextLine();
    }

    static int readInt() {
        return Integer.parseInt(readLn());
    }

    static List<String> readStrings() {
        return Arrays.asList(readLn().split(" "));
    }

    static List<Integer> readInts() {
        List<Integer> result = new ArrayList<>();
        for (String s : readStrings()) {
            result.add(Integer.parseInt(s));
        }
        return result;
    }

    static int findLissPos() {
        String stones = readLn();
        String instructions = readLn();
        int curPos = 0;
        for (int i = 0; i < instructions.length(); i++) {
            if (stones.charAt(curPos) == instructions.charAt(i)) {
                curPos++;
            }
        }

        curPos++;

        return curPos;
    }

    public static void main(String[] args) {
        System.out.print(findLissPos());
    }
}
